#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: AUR publication for one pakmap release.
# The guard and version checks are automated; the SSH pushes and the AUR web
# UI are the human steps. No credentials are entered here — AUR auth is the
# SSH key already installed on the machine.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

DEFAULT_TAG="$(git describe --tags --abbrev=0 2>/dev/null || true)"
banner "AUR publish: pakmap + pakmap-gui"

# ── 1. Preflight + the one checksum both PKGBUILDs need ───────────────────
stage "Preflight: exact tag + source checksum"
say "The guard checks the tag, a clean tree, a pushed HEAD and version drift."
ask RELEASE_TAG "Release tag${DEFAULT_TAG:+ (Enter keeps $DEFAULT_TAG)}:" || RELEASE_TAG="$DEFAULT_TAG"
[[ -n ${RELEASE_TAG:-} ]] || { warn "no tag — aborting"; return 1; }
TAG="$RELEASE_TAG"
if ! bash scripts/aur-publish-guard.sh "$TAG" --network; then
  warn "guard failed — fix the listed issue, then re-run this wizard"
  return 1
fi
step "Copy the 64-hex value from the guard's last 'sha256:' line."
ask PAKMAP_SRC_SHA256 "Source tarball sha256:"
write_env PAKMAP_SRC_SHA256 "$PAKMAP_SRC_SHA256"
write_env RELEASE_TAG "$RELEASE_TAG"

# ── 2. AUR account / SSH ───────────────────────────────────────────────────
stage "AUR account: SSH key in place"
open_url "https://aur.archlinux.org/account/"
step "Account → SSH Public Keys: your current public key must be listed."
step "If it is not, paste ~/.ssh/id_ed25519.pub there and save first."
pause "Key is listed; press Enter to test the connection"
if ssh -o BatchMode=yes -o ConnectTimeout=10 aur@aur.archlinux.org exit >/dev/null 2>&1; then
  say "SSH to AUR works (BatchMode — no password prompt)."
else
  warn "SSH test failed — fix the key before pushing anything"
  return 1
fi

# ── 3. CLI AUR git checkout ───────────────────────────────────────────────
stage "pakmap: local AUR checkout"
ask PAKMAP_AUR_WORKDIR "Directory to hold both AUR checkouts:"
write_env PAKMAP_AUR_WORKDIR "$PAKMAP_AUR_WORKDIR"
mkdir -p "$PAKMAP_AUR_WORKDIR"
if [[ -d "$PAKMAP_AUR_WORKDIR/pakmap/.git" ]]; then
  say "Existing checkout found — will fetch instead of cloning."
else
  open_url "https://aur.archlinux.org/packages/pakmap"
  step "If 'Package not found', use 'Submit' to create the package from packaging/aur/pakmap/PKGBUILD."
  pause "Package exists; press Enter to clone it"
  git clone ssh://aur@aur.archlinux.org/pakmap.git "$PAKMAP_AUR_WORKDIR/pakmap"
fi

# ── 4. CLI PKGBUILD update ────────────────────────────────────────────────
stage "pakmap: update PKGBUILD + .SRCINFO"
cp packaging/aur/pakmap/PKGBUILD "$PAKMAP_AUR_WORKDIR/pakmap/PKGBUILD"
sed -i "s/^sha256sums=.*/sha256sums=('$PAKMAP_SRC_SHA256')/" \
  "$PAKMAP_AUR_WORKDIR/pakmap/PKGBUILD"
( cd "$PAKMAP_AUR_WORKDIR/pakmap" && makepkg --printsrcinfo > .SRCINFO )
step "Review the diff below, then confirm it is exactly this release."
( cd "$PAKMAP_AUR_WORKDIR/pakmap" && git --no-pager diff -- PKGBUILD .SRCINFO )
confirm "CLI PKGBUILD + .SRCINFO are correct?" || { warn "stopped before pushing"; return 1; }

# ── 5. CLI push (irreversible) ────────────────────────────────────────────
stage "pakmap: push to AUR"
say "This publishes v${TAG#v} of the CLI to every AUR user. No undo."
confirm "Push the pakmap package now?" || { warn "skipped the CLI push"; return 1; }
( cd "$PAKMAP_AUR_WORKDIR/pakmap" && \
  git add PKGBUILD .SRCINFO && git commit -m "pakmap ${TAG#v}" && git push )

# ── 6. GUI AUR git checkout ───────────────────────────────────────────────
stage "pakmap-gui: local AUR checkout"
if [[ -d "$PAKMAP_AUR_WORKDIR/pakmap-gui/.git" ]]; then
  say "Existing checkout found — will fetch instead of cloning."
else
  open_url "https://aur.archlinux.org/packages/pakmap-gui"
  step "If 'Package not found', submit packaging/aur/pakmap-gui/PKGBUILD as a new package."
  pause "Package exists; press Enter to clone it"
  git clone ssh://aur@aur.archlinux.org/pakmap-gui.git "$PAKMAP_AUR_WORKDIR/pakmap-gui"
fi

# ── 7. GUI PKGBUILD update ────────────────────────────────────────────────
stage "pakmap-gui: update PKGBUILD + .SRCINFO"
cp packaging/aur/pakmap-gui/PKGBUILD "$PAKMAP_AUR_WORKDIR/pakmap-gui/PKGBUILD"
sed -i "s/^sha256sums=.*/sha256sums=('$PAKMAP_SRC_SHA256')/" \
  "$PAKMAP_AUR_WORKDIR/pakmap-gui/PKGBUILD"
( cd "$PAKMAP_AUR_WORKDIR/pakmap-gui" && makepkg --printsrcinfo > .SRCINFO )
step "Review the diff below, then confirm it is exactly this release."
( cd "$PAKMAP_AUR_WORKDIR/pakmap-gui" && git --no-pager diff -- PKGBUILD .SRCINFO )
confirm "GUI PKGBUILD + .SRCINFO are correct?" || { warn "stopped before pushing"; return 1; }

# ── 8. GUI push (irreversible) ────────────────────────────────────────────
stage "pakmap-gui: push to AUR"
say "This publishes the desktop companion to every AUR user. No undo."
confirm "Push the pakmap-gui package now?" || { warn "skipped the GUI push"; return 1; }
( cd "$PAKMAP_AUR_WORKDIR/pakmap-gui" && \
  git add PKGBUILD .SRCINFO && git commit -m "pakmap-gui ${TAG#v}" && git push )

# ── 9. RPC verification + the docs follow-up ──────────────────────────────
stage "Verify both packages via RPC"
pause "AUR mirrors the push with a small delay; press Enter when ready"
open_url "https://aur.archlinux.org/rpc/v5/info?arg[]=pakmap&arg[]=pakmap-gui"
step "resultcount must be 2 and both Version fields must be ${TAG#v}."
confirm "Both packages are live at ${TAG#v}?" || { warn "verify again before the docs follow-up"; return 1; }
say "Follow-up commit in the main repo: drop 'Not published yet' from README,"
say "add the AUR install commands, and update the landing copy — then push."
say "The guard will now pass: HEAD is tagged and the tree is clean."

finish
}

run_wizard "$@"; exit
